    })

    it("trims both parts before joining", () => {
        expect(
            normalizeRepoFilters(ownerRepoSchema, {owner: " agenta-ai ", repo: " agenta "}),
        ).toEqual({owner: " agenta-ai ", repo: "agenta-ai/agenta"})
    })

